-- Generated by scripts/generate-reputation-event-migration.ts; no financial state mutations.
-- Legacy deployments may predate buyer feedback; reconcile its empty base table.
CREATE TABLE IF NOT EXISTS ratings (
 id TEXT PRIMARY KEY NOT NULL, trade_id TEXT NOT NULL REFERENCES trades(id) ON DELETE CASCADE,
 rater_id TEXT NOT NULL, rated_id TEXT NOT NULL, score INTEGER NOT NULL, comment TEXT,
 created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE UNIQUE INDEX IF NOT EXISTS ratings_trade_rater_unique ON ratings(trade_id,rater_id);
CREATE TABLE IF NOT EXISTS reputation_events (
 id TEXT PRIMARY KEY NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, source_revision TEXT NOT NULL,
 trade_id TEXT NOT NULL, service_order_id TEXT, attempt_id TEXT,
 provider_id TEXT NOT NULL, service_id TEXT, capabilities_json TEXT NOT NULL DEFAULT '[]', contract_json TEXT, agent_version INTEGER,
 event_kind TEXT NOT NULL, occurred_at INTEGER, recorded_at INTEGER NOT NULL, policy_version INTEGER NOT NULL DEFAULT 1,
 buyer_principal TEXT NOT NULL, seller_principal TEXT NOT NULL, historical_related INTEGER NOT NULL, public_eligible INTEGER NOT NULL,
 payload_json TEXT NOT NULL DEFAULT '{}', supersedes_event_id TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS reputation_event_source_revision_idx ON reputation_events(source_type,source_id,source_revision);
CREATE INDEX IF NOT EXISTS reputation_event_provider_trade_idx ON reputation_events(provider_id,trade_id);
CREATE INDEX IF NOT EXISTS reputation_event_trade_kind_idx ON reputation_events(trade_id,event_kind);
CREATE TABLE IF NOT EXISTS reputation_adjudications (
 id TEXT PRIMARY KEY NOT NULL, trade_id TEXT NOT NULL REFERENCES trades(id) ON DELETE RESTRICT,
 actor_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, client_reference TEXT NOT NULL, request_hash TEXT NOT NULL,
 responsibility TEXT NOT NULL, status TEXT NOT NULL, reason TEXT NOT NULL, severity TEXT NOT NULL,
 supersedes_id TEXT UNIQUE REFERENCES reputation_adjudications(id) ON DELETE RESTRICT, created_at INTEGER NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS reputation_decision_origin_idx ON reputation_adjudications(trade_id) WHERE supersedes_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS reputation_decision_reference_idx ON reputation_adjudications(trade_id,client_reference);
CREATE INDEX IF NOT EXISTS reputation_decision_trade_idx ON reputation_adjudications(trade_id,created_at);
