CREATE TABLE IF NOT EXISTS reputation_screening_runs(id TEXT PRIMARY KEY NOT NULL,policy_version INTEGER NOT NULL,fingerprint TEXT UNIQUE NOT NULL,status TEXT NOT NULL,statistics_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reputation_screening_cases(id TEXT PRIMARY KEY NOT NULL,run_id TEXT NOT NULL REFERENCES reputation_screening_runs(id),kind TEXT NOT NULL,trade_ids_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reputation_screening_case_run_idx ON reputation_screening_cases(run_id);
CREATE TABLE IF NOT EXISTS reputation_screening_reviews(id TEXT PRIMARY KEY NOT NULL,case_id TEXT NOT NULL REFERENCES reputation_screening_cases(id),actor_id TEXT NOT NULL REFERENCES users(id),client_reference TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL,supersedes_id TEXT UNIQUE REFERENCES reputation_screening_reviews(id),created_at INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS reputation_screening_review_origin_idx ON reputation_screening_reviews(case_id) WHERE supersedes_id IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS reputation_screening_review_reference_idx ON reputation_screening_reviews(case_id,client_reference);
